// Later seasons can bring their own schedule (see SCHEDULE_Y / PLAYOFFS_Y, keyed by year).
const SCHEDULE_Y = {};
const PLAYOFFS_Y = {};
const scheduleFor = y => SCHEDULE_Y[y] || SCHEDULE;
const playoffsFor = y => PLAYOFFS_Y[y] || PLAYOFFS;
const oppOf = n => { const y = (S && S.year) || 1; return n < 10 ? scheduleFor(y)[n] : playoffsFor(y)[n - 10]; };
const shortName = t => t.split(' ').pop();

// Dante Kingsley's line before a signature Monarchs moment: it remembers your trash-talk choice and which meeting this is.
function kingLine() {
  if (!S) return 'Dante Kingsley is across from you, crown tattoo and all.';
  if ((S.year || 1) > 1) return 'Kingsley again. Whatever happens this year, he still wants to beat you more than anybody.';
  if (S.slate === 9) return 'Kingsley again, on your field this time. The crowd boos every time he touches the ball, and he loves every second of it.';
  if (S.slate >= 10) return 'The third time this season. Kingsley doesn\'t trash talk anymore. He just watches you. You take that as a compliment.';
  return {
    fire: 'Kingsley spots you during warmups and yells across the field: "You bring that receipt, rookie?"',
    cake: 'Before the first snap, Kingsley yells something about cake. The Monarchs sideline laughs. So does yours.',
    quiet: 'You haven\'t said one word about Kingsley all week. He has said plenty about you.',
  }[S.flags.trash] || 'Dante Kingsley is across from you, crown tattoo and all.';
}
// Final-drive follow-ups (fu) never show up in a normal plan, practice or scrimmage.
const fuOnly = () => false;
// Crowd-noise plays only fit a real road game (never camp, never the neutral-site Championship).
const awayGame = () => !!(S && S.role !== 'camp' && typeof venueOf === 'function' && venueOf(S.slate) === 'away');
const leoGame = () => !!(S && S.flags.leoPromise && (S.year || 1) === 1);

